import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { eq } from "drizzle-orm";
import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { getDb, sessions } from "@/server/db";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as digestService from "@/server/services/digest-service";
import * as invitationService from "@/server/services/invitation-service";
import * as memberService from "@/server/services/member-service";
import * as notificationService from "@/server/services/notification-service";
import * as organizationService from "@/server/services/organization-service";
import * as sessionService from "@/server/services/session-service";
import type { SessionId } from "@/types/common";
import { rateLimitState } from "../server/_support/doubles/misc";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

const DAY = 24 * 60 * 60 * 1000;
let cleanup: () => void;
let counter = 0;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

afterEach(() => {
  vi.useRealTimers();
  rateLimitState.allowed = true;
  rateLimitState.remaining = 100;
});

/** Writes an invitation whose raw token the test keeps, so it can be accepted. */
async function issue(
  t: Tenant,
  email: string,
  role: "admin" | "member" | "viewer",
  expiresInDays = 14,
): Promise<{ raw: string }> {
  counter += 1;
  const raw = `scratch-token-${counter}`.padEnd(40, "x");
  await invitationRepo.insertInvitation(
    t.org.id,
    { orgId: t.org.id, email, role, expiresInDays },
    t.userIds.admin,
    hashToken(raw),
  );
  return { raw };
}

async function newUser(email: string) {
  return userRepo.insertUser({ email, name: email, passwordHash: "seed" });
}

describe("scratch verification", () => {
  it("re-admits a former member on the same row with the new invitation's details", async () => {
    const t = await createTenant("rejoin", "growth");
    const email = "contractor@rejoin.test";
    const person = await newUser(email);

    const first = await issue(t, email, "member");
    const original = await invitationService.acceptInvitation(person.id, { token: first.raw });

    await memberService.removeMember(t.actors.owner, {
      orgId: t.org.id,
      memberId: original.id,
    });
    await expect(memberRepo.findMember(t.org.id, person.id)).resolves.toBeNull();
    await expect(memberRepo.countActiveMembers(t.org.id)).resolves.toBe(4);

    const again = await issue(t, email, "viewer");
    const joins: unknown[] = [];
    const off = subscribe("member.joined", (payload) => {
      joins.push(payload);
    });
    const rejoined = await invitationService.acceptInvitation(person.id, { token: again.raw });
    off();

    expect(rejoined.id).toBe(original.id);
    expect(rejoined.role).toBe("viewer");
    expect(rejoined.invitedBy).toBe(t.userIds.admin);
    expect(rejoined.status).toBe("active");
    expect(rejoined.archivedAt).toBeNull();
    expect(rejoined.joinedAt).not.toBeNull();
    expect(joins).toHaveLength(1);
    await expect(memberRepo.countActiveMembers(t.org.id)).resolves.toBe(5);

    const told = await notificationService.listNotifications(t.actors.owner, {
      orgId: t.org.id,
      recipientId: t.userIds.owner,
      unreadOnly: false,
      kind: ["member_joined"],
      limit: 25,
      cursor: null,
    });
    expect(told.total).toBeGreaterThanOrEqual(2);
  });

  it("gives an accepted new member an active row that counts as a seat", async () => {
    const t = await createTenant("fresh-join", "growth");
    const person = await newUser("fresh@fresh-join.test");
    const { raw } = await issue(t, "fresh@fresh-join.test", "member");

    const member = await invitationService.acceptInvitation(person.id, { token: raw });
    expect(member.status).toBe("active");
    await expect(memberRepo.countActiveMembers(t.org.id)).resolves.toBe(5);
    await expect(
      invitationRepo.countPendingInvitations(t.org.id),
    ).resolves.toBe(0);

    // A used-up invitation cannot be accepted again.
    await expect(
      invitationService.acceptInvitation(person.id, { token: raw }),
    ).rejects.toThrow(/already been accepted/);
  });

  it("is valid for 14 days from sending, then expires", async () => {
    const t = await createTenant("expiry", "growth");
    const sent = await invitationService.inviteMember(t.actors.admin, {
      orgId: t.org.id,
      email: "timed@expiry.test",
      role: "member",
    });
    expect(new Date(sent.expiresAt).getTime() - new Date(sent.createdAt).getTime()).toBe(14 * DAY);

    const later = await newUser("late@expiry.test");
    vi.useFakeTimers({ toFake: ["Date"] });
    const base = Date.now();
    const { raw } = await issue(t, "late@expiry.test", "member");

    vi.setSystemTime(base + 13 * DAY);
    await expect(
      invitationService.acceptInvitation(later.id, { token: raw }),
    ).resolves.toBeDefined();

    const stale = await newUser("stale@expiry.test");
    const staleRaw = (await issue(t, "stale@expiry.test", "member")).raw;
    vi.setSystemTime(base + 15 * DAY);
    await expect(
      invitationService.acceptInvitation(stale.id, { token: staleRaw }),
    ).rejects.toThrow(/expired/);
  });

  it("refuses duplicates, existing members and in-batch repeats, creating nothing", async () => {
    const t = await createTenant("dups", "growth");
    await invitationService.inviteMember(t.actors.admin, {
      orgId: t.org.id,
      email: "New@Dups.test",
      role: "member",
    });

    await expect(
      invitationService.inviteMember(t.actors.admin, {
        orgId: t.org.id,
        email: "new@dups.test",
        role: "member",
      }),
    ).rejects.toThrow(/pending/);

    await expect(
      invitationService.inviteMember(t.actors.admin, {
        orgId: t.org.id,
        email: "MEMBER@dups.test",
        role: "member",
      }),
    ).rejects.toThrow(/already a member/);

    const before = await invitationRepo.countPendingInvitations(t.org.id);
    await expect(
      invitationService.inviteMembers(t.actors.admin, {
        orgId: t.org.id,
        invites: [
          { email: "fresh-a@dups.test", role: "member" },
          { email: "FRESH-A@dups.test", role: "viewer" },
        ],
      }),
    ).rejects.toThrow(/more than once/);
    await expect(
      invitationService.inviteMembers(t.actors.admin, {
        orgId: t.org.id,
        invites: [
