    const sent = await invitationService.inviteMember(t.actors.admin, {
      orgId: t.org.id,
      email: "timed@expiry.test",
      role: "member",
    });
    expect(new Date(sent.expiresAt).getTime() - new Date(sent.createdAt).getTime()).toBe(14 * DAY);

    const later = await newUser("late@expiry.test");
    vi.useFakeTimers({ toFake: ["Date"] });
    const base = Date.now();
    const { raw } = await issue(t, "late@expiry.test", "member");

    vi.setSystemTime(base + 13 * DAY);
    await expect(
      invitationService.acceptInvitation(later.id, { token: raw }),
    ).resolves.toBeDefined();

    const stale = await newUser("stale@expiry.test");
    const staleRaw = (await issue(t, "stale@expiry.test", "member")).raw;
    vi.setSystemTime(base + 15 * DAY);
    await expect(
      invitationService.acceptInvitation(stale.id, { token: staleRaw }),
    ).rejects.toThrow(/expired/);
  });

  it("refuses duplicates, existing members and in-batch repeats, creating nothing", async () => {
    const t = await createTenant("dups", "growth");
    await invitationService.inviteMember(t.actors.admin, {
      orgId: t.org.id,
      email: "New@Dups.test",
      role: "member",
    });

    await expect(
      invitationService.inviteMember(t.actors.admin, {
        orgId: t.org.id,
        email: "new@dups.test",
        role: "member",
      }),
    ).rejects.toThrow(/pending/);

    await expect(
      invitationService.inviteMember(t.actors.admin, {
        orgId: t.org.id,
        email: "MEMBER@dups.test",
        role: "member",
      }),
    ).rejects.toThrow(/already a member/);

    const before = await invitationRepo.countPendingInvitations(t.org.id);
    await expect(
      invitationService.inviteMembers(t.actors.admin, {
        orgId: t.org.id,
        invites: [
          { email: "fresh-a@dups.test", role: "member" },
          { email: "FRESH-A@dups.test", role: "viewer" },
        ],
      }),
    ).rejects.toThrow(/more than once/);
    await expect(
      invitationService.inviteMembers(t.actors.admin, {
        orgId: t.org.id,
        invites: [
          { email: "fresh-b@dups.test", role: "member" },
          { email: "admin@dups.test", role: "member" },
        ],
      }),
    ).rejects.toThrow(/already a member/);
    await expect(invitationRepo.countPendingInvitations(t.org.id)).resolves.toBe(before);
  });

  it("frees seats on revoke and on expiry, and refuses past the plan's seats", async () => {
    const t = await createTenant("seats", "starter");
    for (let i = 0; i < 6; i += 1) {
      await invitationService.inviteMember(t.actors.admin, {
        orgId: t.org.id,
        email: `seat-${i}@seats.test`,
        role: "member",
      });
    }
    await expect(
      invitationService.inviteMember(t.actors.admin, {
        orgId: t.org.id,
        email: "over@seats.test",
        role: "member",
      }),
    ).rejects.toThrow(/seats/);

    const pending = await invitationRepo.listPendingInvitations(t.org.id);
    await invitationService.revokeInvitation(t.actors.admin, pending[0]!.id);
    await expect(
      invitationService.inviteMember(t.actors.admin, {
        orgId: t.org.id,
        email: "over@seats.test",
        role: "member",
      }),
    ).resolves.toBeDefined();

    await invitationRepo.insertInvitation(
      t.org.id,
      { orgId: t.org.id, email: "lapsed@seats.test", role: "member", expiresInDays: -1 },
      t.userIds.admin,
      hashToken("lapsed-token".padEnd(40, "y")),
    );
    await expect(invitationRepo.countPendingInvitations(t.org.id)).resolves.toBe(10 - 4);
  });

  it("refuses an invitation accepted by someone other than its address, and keeps it open", async () => {
    const t = await createTenant("forwarded", "growth");
    const { raw } = await issue(t, "intended@forwarded.test", "member");
    const stranger = await newUser("stranger@forwarded.test");

    await expect(
      invitationService.acceptInvitation(stranger.id, { token: raw }),
    ).rejects.toThrow(/different email/);
    await expect(invitationRepo.countPendingInvitations(t.org.id)).resolves.toBe(1);

    const intended = await newUser("Intended@Forwarded.test".toLowerCase());
    await expect(
      invitationService.acceptInvitation(intended.id, { token: raw }),
    ).resolves.toMatchObject({ role: "member" });
  });

  it("refuses to accept into a deleted workspace", async () => {
    const t = await createTenant("gone", "growth");
    const { raw } = await issue(t, "later@gone.test", "member");
    const person = await newUser("later@gone.test");

    await organizationService.deleteOrganization(t.actors.owner, {
      orgId: t.org.id,
      confirmSlug: t.org.slug,
    });
    await expect(
      invitationService.acceptInvitation(person.id, { token: raw }),
    ).rejects.toThrow(/deleted/);
    expect((await orgRepo.findOrgById(t.org.id))?.archivedAt).not.toBeNull();
  });

  it("re-sends an expired invitation with its role and a fresh 14-day window", async () => {
    const t = await createTenant("resend", "growth");
    const first = await invitationService.inviteMember(t.actors.admin, {
      orgId: t.org.id,
      email: "viewer-to-be@resend.test",
      role: "viewer",
    });

    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(Date.now() + 15 * DAY);
    const second = await invitationService.resendInvitation(t.actors.admin, first.id);

    expect(second.id).not.toBe(first.id);
    expect(second.role).toBe("viewer");
    expect(second.email).toBe("viewer-to-be@resend.test");
    expect(new Date(second.expiresAt).getTime() - new Date(second.createdAt).getTime()).toBe(14 * DAY);

    const open = await invitationRepo.listPendingInvitations(t.org.id);
    expect(open.map((row) => row.id)).toContain(second.id);
    expect(open.map((row) => row.id)).not.toContain(first.id);
  });

  it("stops notifying and digesting a removed member, and clears their sessions' default", async () => {
    const t = await createTenant("leave", "growth");
    await preferenceRepo.upsertPreference({
      orgId: t.org.id,
      userId: t.userIds.member,
      kind: "comment_created",
      inApp: true,
      email: false,
      digestOnly: true,
    });
    await expect(digestService.listDigestRecipients(t.org.id)).resolves.toContain(t.userIds.member);

    const { token } = await sessionService.createSessionToken(t.userIds.member);
    const row = getDb()
      .select()
      .from(sessions)
      .where(eq(sessions.tokenHash, hashToken(token)))
      .get();
    await sessionRepo.setActiveOrg(row!.id as SessionId, t.org.id);
    await expect(sessionService.resolveSession(token)).resolves.toMatchObject({
      activeOrgId: t.org.id,
    });

    const { token: otherToken } = await sessionService.createSessionToken(t.userIds.member);
    const other = await createTenant("leave-other", "growth");
    const otherRow = getDb()
      .select()
      .from(sessions)
      .where(eq(sessions.tokenHash, hashToken(otherToken)))
      .get();
    await sessionRepo.setActiveOrg(otherRow!.id as SessionId, other.org.id);

    const membership = await memberRepo.findMember(t.org.id, t.userIds.member);
    await memberService.removeMember(t.actors.owner, {
      orgId: t.org.id,
      memberId: membership!.id,
    });

    await expect(digestService.listDigestRecipients(t.org.id)).resolves.not.toContain(t.userIds.member);
    await expect(
      notificationService.notify(t.org.id, "comment_created", [t.userIds.member], {
        title: "x",
        body: "x",
        href: "/x",
        actorId: null,
      }),
    ).resolves.toHaveLength(0);

    await expect(sessionService.resolveSession(token)).resolves.toMatchObject({
      activeOrgId: null,
    });
    await expect(sessionService.resolveSession(otherToken)).resolves.toMatchObject({
      activeOrgId: other.org.id,
    });
  });
});

