/**
 * Bulk invite. The seat quota is checked once for the whole batch — inviting
 * five people into a plan with three free seats must fail as a batch rather
 * than half-succeeding — and the rate limit is charged per invite. Every check
 * runs before the first row is written, so a refused batch creates nothing.
 */
export async function inviteMembers(
  actor: Actor,
  input: InviteMembersInput,
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:invite", orgResource(input.orgId));

  return issueInvitations(actor, input.orgId, input.invites, null);
}

/**
 * Shared by a fresh invite and a re-send. `replacing` is the invitation a
 * re-send withdraws: it is set aside while the checks run, so it neither blocks
 * its own address nor holds a seat against the new one.
 */
async function issueInvitations(
  actor: Actor,
  orgId: OrgId,
  invites: readonly InviteRequest[],
  replacing: Invitation | null,
): Promise<readonly Invitation[]> {
  const verdict = await consumeRateLimit(orgId, INVITE_BUCKET, invites.length);
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  if (org.archivedAt !== null) {
    throw new Error("That organization has been deleted");
  }

  const requests = invites.map((invite) => ({
    email: invite.email.toLowerCase(),
    role: invite.role,
  }));
  if (new Set(requests.map((request) => request.email)).size !== requests.length) {
    throw new Error("The same address appears more than once in this batch");
  }

  for (const request of requests) {
    await refuseUnavailableAddress(orgId, request.email, replacing);
  }

  const now = new Date();
  const seatReleased = replacing !== null && isPending(replacing, now) ? 1 : 0;
  const seatsUsed =
    (await memberRepo.countActiveMembers(orgId)) +
    (await invitationRepo.countPendingInvitations(orgId)) -
    seatReleased;

  if (wouldExceedLimit(org.plan, "seats", seatsUsed, requests.length)) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  if (replacing !== null) {
    await invitationRepo.revokeInvitation(orgId, replacing.id);
  }

  const invitations: Invitation[] = [];

  for (const request of requests) {
    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      orgId,
      {
        orgId,
        email: request.email,
        role: request.role,
        expiresInDays: DEFAULT_EXPIRY_DAYS,
      },
      actor.userId,
      hashToken(token),
    );

    invitations.push(invitation);

    await emit("member.invited", {
      orgId,
      actorId: actor.userId,
      occurredAt: invitation.createdAt,
      email: invitation.email,
      role: invitation.role,
    });
  }

  return invitations;
}

